CREATE TRIGGER matched_entries_fts_au AFTER UPDATE ON matched_entries BEGIN
                INSERT INTO matched_entries_fts(matched_entries_fts, rowid, title, summary, abstract, authors)
                VALUES ('delete', old.rowid, old.title, old.summary, old.abstract, old.authors);
                INSERT INTO matched_entries_fts(rowid, title, summary, abstract, authors)
                VALUES (new.rowid, new.title, new.summary, new.abstract, new.authors);
            END

